{
  "title": "Welcome Campaign",
  "message": "Welcome to our service! How can we help you today?",
  "inbox_id": 1,
  "enabled": true,
  "trigger_only_during_business_hours": false,
  "trigger_rules": {
    "time_on_page": 10,
    "url": "https://mywebsite.com/pricing"
  }
}

{
  "name": "Close and Tag",
  "visibility": "global",
  "actions": [
    {"action_name": "add_label", "action_params": ["resolved"]},
    {"action_name": "resolve_conversation", "action_params": []},
    {"action_name": "send_message", "action_params": ["Thank you for contacting us!"]}
  ]
}

{
  "name": "Team Lead",
  "description": "Team lead with limited admin access",
  "permissions": ["conversation_manage", "contact_manage", "report_view"]
}

{
  "name": "Auto-assign Sales",
  "description": "Auto assign to sales team",
  "event_name": "conversation_created",
  "active": true,
  "conditions": [
    {"attribute_key": "inbox_id", "filter_operator": "equal_to", "values": [1]}
  ],
  "actions": [
    {"action_name": "assign_team", "action_params": [1]}
  ]
}

{
  "name": "Sales Team Chat",
  "description": "Internal chat for sales team"
}
